<script setup>
import { ArrowUpRight } from 'lucide-vue-next'
const route = useRoute()
const localeCodes = new Set(['zh', 'ru', 'de', 'fr', 'ja', 'ko', 'es', 'pt', 'tr'])
const localeRoot = localeCodes.has(String(route.params.slug || ''))
if (localeRoot) onMounted(() => navigateTo('/', { replace: true }))
const pages = {
  privacy: { title:'Privacy, in plain language', intro:'Your story belongs to you. Moovicut is local-first by design.', sections:[['What stays on your device','Your premise, storyboards, prompts and preferences are stored in this browser, or in JSON files you choose to export. The local story engine does not upload them to a Moovicut server. The public site also counts anonymous page views, without cookies and without storing IP addresses.'],['No account','Moovicut does not create an account. The storyboard stays in this browser and is not sent to a Moovicut server.'],['What this app does not do','It does not automatically submit your prompts to Grok Imagine, Google or an AI model. It does not generate video itself. It does not include third-party advertising pixels. Your model subscriptions, credits, rendered clips and account usage remain entirely between you and the relevant platform.'],['AI agents and project files','An AI agent running in your authorized environment may read or create JSON through the documented interface. Browser agent access is limited to the active project.'],['Your choices','Work in this browser without an account, export your project as portable JSON, or clear saved browser data through your browser settings. If your project data matters, keep your own JSON backups.'],['Contact and deployment','This is a locally delivered software workspace. The person deploying a hosted version must provide its operator contact, production identity handling, retention policy and any additional privacy notices required for that deployment.']] },
  terms: { title:'A fair agreement for your creative work', intro:'Moovicut gives you a planning space; you remain responsible for the stories and videos you choose to make.', sections:[['Your creative ownership','You retain your rights in premises you enter and storyboards you create, to the extent that applicable law provides them. The tool itself is provided under its software project license.'],['Model platforms','Names of other companies refer only to compatible prompt targets or optional external services. Their account terms, content rules, usage limits, rates and model results are outside our control.'],['A planning tool, not a generator','The current engine uses deterministic local rules to create editable shot suggestions and prompt drafts. It does not pretend to call a remote AI model or render videos. You choose whether and where to use those prompts.'],['Acceptable use','Use the application lawfully and respect the rights and dignity of other people. Do not use it to plan or facilitate harm, deception, unauthorized impersonation or exploitative content. Review any generated prompt before using it in a third-party system.'],['Availability and warranty','The software is offered as-is, without guarantees of uninterrupted service or fitness for a particular purpose. Save copies of important projects. Local browser data can be removed by clearing storage or changing devices.'],['Production operator','A public deployment’s operator must provide its contact and entity details and review these terms for its jurisdiction and authentication configuration.']] },
  'content-policy': { title:'Make something worth sharing', intro:'Room for imagination still leaves room for care.', sections:[['Respect people','Avoid sexual exploitation, content involving minors, non-consensual intimate imagery, targeted harassment and unauthorized impersonation. Respect privacy, agency and the people represented in your story.'],['Avoid harm','Do not use the app to plan violence, abuse, fraud, incitement or real-world harm. Sensitive fictional themes deserve thoughtful, contextual treatment.'],['Respect original work','Use premises, footage and identities you have permission to work with. A model platform may refuse content under its own policy even when Moovicut lets you draft a prompt.'],['You are the director','Local prompts are starting points. Check the prompt’s meaning, visual representation and continuity before use. You decide what to paste into a third-party service and what to publish.'],['No automated video rendering','Moovicut’s first release only creates structure and text. Nothing is submitted for video generation by the app. You control your own accounts and tools.'],['Changes to services','Model providers evolve. Keep your projects backed up as JSON and consult each provider’s current policy before generation or distribution.']] }
}
const page = pages[route.params.slug] || { title:'Page not found', intro:'This address is not part of Moovicut.', sections:[], missing:true }
useSeoMeta({ title: `${page.title} — Moovicut` })
</script>
<template><div class="site-shell"><AppHeader /><main class="legal-page"><div class="container-docs"><div class="page-intro"><p class="eyebrow">MOOVICUT · THE CLEAR VERSION</p><h1>{{ page.title }}</h1><p>{{ page.intro }}</p></div><section v-for="section in page.sections" :key="section[0]" class="legal-section"><h2>{{ section[0] }}</h2><p>{{ section[1] }}</p></section><div class="legal-bottom"><p v-if="!page.missing">Updated November 2026</p><NuxtLink to="/" class="button button-primary">{{ page.missing ? 'Back to Moovicut' : 'Back to the studio' }} <ArrowUpRight :size="15" /></NuxtLink></div></div></main><SiteFooter /><AppToast /></div></template>
